insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"verbs_to_be_homework_q01_finish","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\verbs_to_be_homework.yaml","source_metadata":{}},{"key":"verbs_to_be_homework_q01_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\verbs_to_be_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"verbs_to_be_homework_q01_finish","locale":"he","line_order":0,"content":"הלוח מוכן. מחר הילדים החדשים ילמדו מהמשפטים שלכם, כמו שאני למדתי מכם.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_homework_q01_finish","locale":"he","line_order":1,"content":"זכרו: I am = אני. He is = הוא, She is = היא, It is = זה. We are = אנחנו, You are = אתה, את או אתם, They are = הם או הן.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_homework_q01_finish","locale":"he","line_order":2,"content":"כל הכבוד. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_homework_q01_start","locale":"he","line_order":0,"content":"שלום שוב! בזכותכם אני זוכרת את כל החוקים, והשומרים לא גילו כלום.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_homework_q01_start","locale":"he","line_order":1,"content":"מחר מגיעים לממלכה ילדים חדשים, כמו שאתם הגעתם. והפעם אני אלמד אותם בעצמי.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_homework_q01_start","locale":"he","line_order":2,"content":"היום אין חוק חדש. אני רק רוצה לראות שאתם זוכרים הכול לבד.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_homework_q01_start","locale":"he","line_order":3,"content":"כל משפט נכון שלכם אכתוב על הלוח לשיעור של מחר. התיבה ליד המים מחכה לכם.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
